values
  ('pregnancy', 'pregnancy', 1, 'en-US', '{"sections": [{"id": "pregnancy", "questions": [{"field_id": "PRG_DATES_METHOD", "format": "single_choice", "required": true, "options": ["gestational_age", "edd", "unknown"], "option_labels": {"gestational_age": "I know gestational age", "edd": "I know EDD", "unknown": "I do not know yet"}, "label": "What is the easiest way for you to enter how far along you are?", "hint": "Choose the easiest way to tell us about your pregnancy."}, {"field_id": "PRG_GESTATIONAL_WEEKS", "format": "number", "profile_path": "pregnancy.gestational_weeks", "required": false, "show_if": {"field_id": "PRG_DATES_METHOD", "in": ["gestational_age"]}, "min": 1, "max": 45, "label": "How many weeks pregnant are you?"}, {"field_id": "PRG_EDD", "format": "date", "profile_path": "pregnancy.edd", "required": false, "show_if": {"field_id": "PRG_DATES_METHOD", "in": ["edd"]}, "date_constraint": "future_or_today", "min_future_days": 7, "max_future_days": 294, "label": "What''s your due date?"}, {"field_id": "PRG_LMP", "format": "date", "profile_path": "pregnancy.lmp", "required": false, "show_if": {"field_id": "PRG_DATES_METHOD", "in": ["unknown"]}, "date_constraint": "past_or_today", "max_past_days": 308, "min_past_days": 14, "extra_option": "i_do_not_remember", "label": "Do you remember when your last period started?", "hint": "This helps us estimate your due date automatically.", "extra_option_label": "I do not remember"}, {"field_id": "PRG_MULTIPLES", "format": "single_choice", "profile_path": "pregnancy.multiples", "options": ["one_baby", "twins", "triplets", "more_than_three", "unknown", "prefer_not_to_say"], "option_labels": {"one_baby": "One baby", "twins": "Twins", "triplets": "Triplets", "more_than_three": "More than three", "unknown": "I do not know yet", "prefer_not_to_say": "Prefer not to answer"}, "label": "How many babies are you expecting?"}, {"field_id": "PRG_GOALS", "format": "multi_choice", "max_select": 3, "profile_path": "pregnancy.goals", "options": ["understand_development", "understand_body_changes", "manage_symptoms", "prepare_appointments", "eat_manageable", "stay_active_safely", "feel_less_anxious", "prepare_labor", "prepare_life_after_birth", "support_partner_relationship"], "option_labels": {"understand_development": "Understand how my baby or babies are developing", "understand_body_changes": "Understand changes in my body", "manage_symptoms": "Manage symptoms", "prepare_appointments": "Prepare for appointments and tests", "eat_manageable": "Eat in a way that feels manageable and supportive", "stay_active_safely": "Stay active safely", "feel_less_anxious": "Feel less anxious", "prepare_labor": "Prepare for labor and delivery", "prepare_life_after_birth": "Prepare for life after birth", "support_partner_relationship": "Support my relationship with my partner"}, "label": "What feels most important to you right now?"}, {"field_id": "PRG_CARE", "format": "single_choice", "profile_path": "pregnancy.care", "options": ["regular_appointments", "first_scheduled", "choosing_provider", "not_started_yet", "also_maternal_fetal_specialist", "prefer_not_to_say"], "option_labels": {"regular_appointments": "I have regular prenatal appointments", "first_scheduled": "My first appointment is scheduled", "choosing_provider": "I am still choosing an OB-GYN, midwife, or clinic", "not_started_yet": "Prenatal care has not started yet", "also_maternal_fetal_specialist": "I am also seeing a maternal-fetal medicine or high-risk specialist", "prefer_not_to_say": "Prefer not to answer"}, "label": "What kind of prenatal care do you have right now?"}, {"field_id": "PRG_SPECIAL_CARE", "format": "multi_choice", "profile_path": "pregnancy.special_care", "sensitivity_level": "health", "options": ["routine_so_far", "need_frequent_monitoring", "exercise_limits", "work_travel_limits", "food_medication_instructions", "advised_rest", "not_discussed_yet", "prefer_not_to_say"], "option_labels": {"routine_so_far": "Everything is routine so far", "need_frequent_monitoring": "I need more frequent monitoring", "exercise_limits": "I have limits on exercise or physical activity", "work_travel_limits": "I have limits related to work or travel", "food_medication_instructions": "I have special instructions about food or medication", "advised_rest": "I was advised to rest or reduce activity", "not_discussed_yet": "I have not discussed this with my care team yet", "prefer_not_to_say": "Prefer not to answer"}, "label": "Has your care team asked you to follow any special monitoring or restrictions?"}, {"field_id": "PRG_SYMPTOMS", "format": "multi_choice", "max_select": 5, "profile_path": "pregnancy.symptoms", "sensitivity_level": "health", "options": ["nausea", "fatigue", "sleepiness", "trouble_sleeping", "back_pelvic_pain", "heartburn", "constipation_bloating", "headaches", "swelling", "shortness_of_breath", "anxiety", "mood_changes", "nothing_much", "something_else"], "option_labels": {"nausea": "Nausea or vomiting", "fatigue": "Strong fatigue", "sleepiness": "Sleepiness", "trouble_sleeping": "Trouble sleeping", "back_pelvic_pain": "Back or pelvic pain", "heartburn": "Heartburn", "constipation_bloating": "Constipation or bloating", "headaches": "Headaches", "swelling": "Swelling", "shortness_of_breath": "Shortness of breath", "anxiety": "Anxiety", "mood_changes": "Mood changes", "nothing_much": "Nothing is bothering me much", "something_else": "Something else"}, "label": "What is bothering you most right now?"}, {"field_id": "PRG_PREG_HISTORY", "format": "multi_choice", "profile_path": "pregnancy.previous_history", "sensitivity_level": "highly_sensitive", "options": ["first_pregnancy", "ended_in_birth", "miscarriage", "chose_to_end", "ended_medical_reasons", "ectopic_or_molar", "more_than_one", "prefer_not_to_say"], "option_labels": {"first_pregnancy": "No, this is my first pregnancy", "ended_in_birth": "Yes, and the pregnancy ended in birth", "miscarriage": "I had a miscarriage", "chose_to_end": "I chose to end a pregnancy", "ended_medical_reasons": "A pregnancy was ended for medical reasons", "ectopic_or_molar": "I had an ectopic or molar pregnancy", "more_than_one": "I have had more than one of these experiences", "prefer_not_to_say": "Prefer not to answer"}, "label": "Have you ever been pregnant before?"}, {"field_id": "PRG_PREV_DETAILS", "format": "multi_choice", "profile_path": "pregnancy.previous_details", "sensitivity_level": "health", "show_if": {"not": {"field_id": "PRG_PREG_HISTORY", "selected_any_in": ["first_pregnancy"]}}, "options": ["c_section", "preterm_birth", "high_bp_preeclampsia", "gestational_diabetes", "heavy_blood_loss", "repeated_loss", "surgery_uterus", "something_else", "no", "not_sure", "prefer_not_to_say"], "option_labels": {"c_section": "C-section", "preterm_birth": "Preterm birth", "high_bp_preeclampsia": "High blood pressure or preeclampsia", "gestational_diabetes": "Gestational diabetes", "heavy_blood_loss": "Heavy blood loss", "repeated_loss": "Repeated pregnancy loss", "surgery_uterus": "Surgery involving the uterus", "something_else": "Something else", "no": "No", "not_sure": "I am not sure", "prefer_not_to_say": "Prefer not to answer"}, "label": "Has your care team asked you to keep anything from a previous pregnancy or birth in mind?"}, {"field_id": "PRG_CURRENT_CONTEXT", "format": "multi_choice", "profile_path": "pregnancy.current_monitoring", "sensitivity_level": "health", "options": ["blood_pressure", "blood_sugar", "anemia_iron", "thyroid", "preterm_labor_risk", "placenta_bleeding", "baby_growth", "something_else", "no", "dont_know_yet", "prefer_not_to_say"], "option_labels": {"blood_pressure": "Blood pressure", "blood_sugar": "Blood sugar", "anemia_iron": "Anemia or iron levels", "thyroid": "Thyroid health", "preterm_labor_risk": "Risk of preterm labor", "placenta_bleeding": "Placenta location or bleeding", "baby_growth": "Growth of the baby or babies", "something_else": "Something else", "no": "No", "dont_know_yet": "I do not know yet", "prefer_not_to_say": "Prefer not to answer"}, "label": "Is your care team watching anything especially closely right now?"}, {"field_id": "PRG_MEDS", "format": "multi_choice", "profile_path": "pregnancy.medications", "options": ["prenatal_vitamin", "folic_acid", "iron", "vitamin_d", "clinician_prescribed", "other_supplements", "nothing_right_now", "prefer_not_to_say"], "option_labels": {"prenatal_vitamin": "Prenatal vitamin", "folic_acid": "Folic acid", "iron": "Iron", "vitamin_d": "Vitamin D", "clinician_prescribed": "Medication prescribed by a clinician", "other_supplements": "Other supplements", "nothing_right_now": "Nothing right now", "prefer_not_to_say": "Prefer not to answer"}, "label": "What are you currently taking on a regular basis?"}, {"field_id": "PRG_FAMILY_CONTEXT", "format": "single_choice", "profile_path": "pregnancy.family_context_status", "options": ["testing_complete", "testing_scheduled", "next_step_undecided", "no", "not_discussed_yet", "not_sure", "prefer_not_to_say"], "option_labels": {"testing_complete": "Yes, the recommended testing is complete", "testing_scheduled": "Yes, testing or counseling is scheduled", "next_step_undecided": "Yes, but the next step has not been decided", "no": "No", "not_discussed_yet": "We have not discussed this yet", "not_sure": "I am not sure", "prefer_not_to_say": "Prefer not to answer"}, "label": "Has your care team recommended extra testing or counseling because of family history?"}, {"field_id": "PRG_FAMILY_DETAILS", "format": "multi_choice", "profile_path": "pregnancy.family_details", "sensitivity_level": "health", "show_if": {"field_id": "PRG_FAMILY_CONTEXT", "in": ["testing_complete", "testing_scheduled", "next_step_undecided"]}, "options": ["condition_in_several_relatives", "congenital_condition", "developmental_condition", "repeated_loss_or_stillbirth", "genetic_counseling_appointment", "something_else", "dont_know_exact_name", "prefer_not_to_say"], "option_labels": {"condition_in_several_relatives": "A condition that appears in several relatives", "congenital_condition": "A congenital condition or serious illness present from birth", "developmental_condition": "A developmental condition in a child in the family", "repeated_loss_or_stillbirth": "Repeated pregnancy loss or stillbirth in the family", "genetic_counseling_appointment": "A genetic counseling appointment", "something_else": "Something else", "dont_know_exact_name": "I do not know the exact name", "prefer_not_to_say": "Prefer not to answer"}, "label": "What did your care team recommend keeping in mind?"}, {"field_id": "PRG_OCCUPATION", "format": "single_choice", "profile_path": "person.occupation_category", "options": ["work", "student", "manage_household", "on_leave_not_working", "enter_job", "prefer_not_to_say"], "option_labels": {"work": "I work", "student": "I am a student", "manage_household": "I manage a household or care for other people", "on_leave_not_working": "I am on leave or not currently working", "enter_job": "Optional: briefly enter your job or field", "prefer_not_to_say": "Prefer not to answer"}, "label": "What best describes what you do right now?"}, {"field_id": "PRG_OCCUPATION_DETAIL", "format": "short_text", "profile_path": "person.occupation_detail", "required": false, "max_length": 80, "show_if": {"field_id": "PRG_OCCUPATION", "in": ["enter_job"]}, "label": "Your job or field"}, {"field_id": "PRG_WORK_NATURE", "format": "multi_choice", "max_select": 2, "profile_path": "person.work_nature", "options": ["mostly_sitting", "on_feet_long", "physical_lifting", "high_emotional_responsibility", "shift_overnight", "traveling_commuting", "can_take_breaks", "hard_to_take_breaks", "every_day_different"], "option_labels": {"mostly_sitting": "Mostly sitting", "on_feet_long": "On my feet for long periods", "physical_lifting": "Physical work or lifting", "high_emotional_responsibility": "High emotional responsibility", "shift_overnight": "Shift work or overnight work", "traveling_commuting": "Frequently traveling or commuting", "can_take_breaks": "I can take breaks when I need them", "hard_to_take_breaks": "It is very hard to take breaks", "every_day_different": "Every day is different"}, "label": "What is most of your day like?"}, {"field_id": "PRG_ACTIVITY", "format": "single_choice", "profile_path": "pregnancy.activity", "options": ["continuing_with_approval", "light_activity_walks", "moving_less_symptoms", "already_demanding", "clinician_limited", "not_sure_whats_safe", "prefer_not_to_say"], "option_labels": {"continuing_with_approval": "I am continuing my usual exercise with my clinician''s approval", "light_activity_walks": "I am choosing light activity and walks", "moving_less_symptoms": "I am moving less because of symptoms", "already_demanding": "Work or caregiving is already physically demanding", "clinician_limited": "My clinician has limited my activity", "not_sure_whats_safe": "I am not sure what is safe right now", "prefer_not_to_say": "Prefer not to answer"}, "label": "What does movement and exercise look like for you right now?"}, {"field_id": "PRG_SLEEP", "format": "single_choice", "profile_path": "person.sleep", "options": ["mostly_okay", "not_enough", "trouble_falling_asleep", "wake_often", "symptoms_interrupt", "shift_overnight", "every_day_different", "prefer_not_to_say"], "option_labels": {"mostly_okay": "Mostly okay", "not_enough": "I often do not get enough sleep", "trouble_falling_asleep": "I have trouble falling asleep", "wake_often": "I wake up often", "symptoms_interrupt": "Symptoms are interrupting my sleep", "shift_overnight": "I work shifts or overnight", "every_day_different": "Every day is different", "prefer_not_to_say": "Prefer not to answer"}, "label": "What has sleep been like lately?"}, {"field_id": "PRG_EATING", "format": "multi_choice", "max_select": 2, "profile_path": "pregnancy.eating", "options": ["about_the_same", "nausea_limits", "appetite_changed", "cant_eat_regular_times", "specific_dietary_instructions", "allergies_restrictions", "worry_eating_right", "prefer_not_to_say"], "option_labels": {"about_the_same": "I can eat about the same as usual", "nausea_limits": "Nausea limits what I can eat", "appetite_changed": "My appetite has changed a lot", "cant_eat_regular_times": "I often cannot eat at regular times", "specific_dietary_instructions": "My care team gave me specific dietary instructions", "allergies_restrictions": "I have food allergies, restrictions, or personal dietary preferences", "worry_eating_right": "I worry about whether I am eating the right things", "prefer_not_to_say": "Prefer not to answer"}, "label": "What is eating like for you right now?"}, {"field_id": "PRG_MENTAL", "format": "multi_choice", "max_select": 3, "profile_path": "person.emotional_baseline", "sensitivity_level": "health", "options": ["calm", "happy", "tired", "overwhelmed", "anxious", "irritable", "sad", "disconnected", "hard_to_feel_happy_about_pregnancy", "emotions_change_often", "hard_to_tell", "prefer_not_to_say"], "option_labels": {"calm": "Calm", "happy": "Happy", "tired": "Tired", "overwhelmed": "Overwhelmed", "anxious": "Anxious", "irritable": "Irritable", "sad": "Sad", "disconnected": "Disconnected", "hard_to_feel_happy_about_pregnancy": "It is hard for me to feel happy about the pregnancy", "emotions_change_often": "My emotions change often", "hard_to_tell": "It is hard for me to tell", "prefer_not_to_say": "Prefer not to answer"}, "label": "How have you felt most often over the past two weeks?"}, {"field_id": "PRG_FEARS", "format": "multi_choice", "max_select": 2, "profile_path": "pregnancy.fears", "sensitivity_level": "highly_sensitive", "options": ["babys_health", "my_own_health", "symptoms_body_changes", "test_results", "labor_delivery", "pregnancy_loss", "money_or_work", "my_relationship", "life_after_baby_arrives", "none_right_now", "prefer_not_to_say"], "option_labels": {"babys_health": "The health of my baby or babies", "my_own_health": "My own health", "symptoms_body_changes": "Symptoms or body changes", "test_results": "Test results", "labor_delivery": "Labor and delivery", "pregnancy_loss": "Pregnancy loss", "money_or_work": "Money or work", "my_relationship": "My relationship", "life_after_baby_arrives": "Life after the baby or babies arrive", "none_right_now": "None of these right now", "prefer_not_to_say": "Prefer not to answer"}, "label": "What worries you most right now?"}, {"field_id": "PRG_SUPPORT_NETWORK", "format": "multi_choice", "profile_path": "pregnancy.support_network", "options": ["partner", "family", "friends", "clinician", "therapist_support_group", "very_little_help", "prefer_not_to_say"], "option_labels": {"partner": "Partner", "family": "Family", "friends": "Friends", "clinician": "OB-GYN, midwife, or another clinician", "therapist_support_group": "Therapist or support group", "very_little_help": "I have very little help right now", "prefer_not_to_say": "Prefer not to answer"}, "label": "Who can you realistically rely on for help?"}, {"field_id": "PRG_REST", "format": "multi_choice", "max_select": 3, "profile_path": "person.recovery_activities", "options": ["work_school", "walk", "exercise_movement", "music", "reading_movies_shows", "creative_activities", "time_with_people", "time_alone", "travel_nature", "not_sure_yet", "something_else"], "option_labels": {"work_school": "Work or school", "walk": "A walk", "exercise_movement": "Exercise or movement", "music": "Music", "reading_movies_shows": "Reading, movies, or shows", "creative_activities": "Creative activities", "time_with_people": "Spending time with people", "time_alone": "Time alone", "travel_nature": "Travel or nature", "not_sure_yet": "I am not sure yet", "something_else": "Something else"}, "label": "What helps you feel like yourself, not only like a pregnant person?"}, {"field_id": "PRG_PARTNER", "format": "single_choice", "profile_path": "person.partner_status", "required": false, "skippable": true, "options": ["yes_live_together", "yes_no_live_together", "casual_multiple", "no_partner", "prefer_not_to_say"], "option_labels": {"yes_live_together": "Yes, we live together", "yes_no_live_together": "Yes, but we do not live together", "casual_multiple": "I have casual or multiple partners", "no_partner": "I do not currently have a partner", "prefer_not_to_say": "Prefer not to answer"}, "label": "Do you currently have a partner?"}, {"field_id": "PRG_PARTNER_SUPPORT", "format": "single_choice", "profile_path": "person.partner_support", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "show_if": {"field_id": "PRG_PARTNER", "in": ["yes_live_together", "yes_no_live_together", "casual_multiple"]}, "options": ["understands_supports", "tries_not_always", "emotionally_supportive_but_responsibilities_fall_on_me", "hard_to_ask_for_help", "little_support", "relationship_tense", "pressured_unsafe", "prefer_not_to_say"], "option_labels": {"understands_supports": "They understand and support me well", "tries_not_always": "They try, but do not always know how to help", "emotionally_supportive_but_responsibilities_fall_on_me": "They are emotionally supportive, but most daily responsibilities fall to me", "hard_to_ask_for_help": "It is hard for me to ask for help", "little_support": "I get very little support", "relationship_tense": "The relationship feels tense right now", "pressured_unsafe": "I feel pressured or unsafe", "prefer_not_to_say": "Prefer not to answer"}, "label": "How involved is your partner in the pregnancy and your well-being?"}, {"field_id": "PRG_SEX_ACTIVE", "format": "single_choice", "profile_path": "pregnancy.sexual_activity", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "options": ["yes_regularly", "sometimes", "not_right_now", "care_team_advised_avoid", "prefer_not_to_say"], "option_labels": {"yes_regularly": "Yes, regularly", "sometimes": "Sometimes", "not_right_now": "Not right now", "care_team_advised_avoid": "My care team advised us to avoid sex", "prefer_not_to_say": "Prefer not to answer"}, "label": "Is sexual activity part of your life right now?"}, {"field_id": "PRG_SEX_FREQ", "format": "single_choice", "profile_path": "pregnancy.sex_frequency", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "show_if": {"field_id": "PRG_SEX_ACTIVE", "in": ["yes_regularly", "sometimes"]}, "options": ["few_times_week", "about_once_week", "few_times_month", "less_often", "varies_a_lot", "prefer_not_to_say"], "option_labels": {"few_times_week": "A few times a week", "about_once_week": "About once a week", "few_times_month": "A few times a month", "less_often": "Less often", "varies_a_lot": "It varies a lot", "prefer_not_to_say": "Prefer not to answer"}, "label": "How often do you usually have sex or sexual contact?"}, {"field_id": "PRG_INTIMACY", "format": "multi_choice", "profile_path": "pregnancy.intimacy_changes", "sensitivity_level": "highly_sensitive", "required": false, "skippable": true, "show_if": {"field_id": "PRG_SEX_ACTIVE", "in": ["yes_regularly", "sometimes"]}, "options": ["nothing_changed", "desire_increased", "desire_decreased", "pain_discomfort", "worry_harm_pregnancy", "partner_worries_harm", "want_affection_without_sex", "care_team_restrictions", "want_help_talking", "prefer_not_to_say"], "option_labels": {"nothing_changed": "Nothing important has changed", "desire_increased": "My desire has increased", "desire_decreased": "My desire has decreased", "pain_discomfort": "I sometimes have pain or discomfort", "worry_harm_pregnancy": "I worry that sex could harm the pregnancy", "partner_worries_harm": "My partner worries that sex could harm the pregnancy", "want_affection_without_sex": "I want affection without sex", "care_team_restrictions": "My care team has given us restrictions", "want_help_talking": "I would like help talking with my partner", "prefer_not_to_say": "Prefer not to answer"}, "label": "What has changed about intimacy during pregnancy?"}, {"field_id": "PRG_BEHAVIOR", "format": "paired_choice", "profile_path": "person.behavior", "rows": [{"row_id": "planning", "options": ["clear_plan", "flexible_suggestions"], "option_labels": {"clear_plan": "Clear plan", "flexible_suggestions": "Flexible suggestions"}}, {"row_id": "depth", "options": ["action_first", "explain_first"], "option_labels": {"action_first": "Give me the action first", "explain_first": "Explain it first"}}, {"row_id": "length", "options": ["brief", "detailed"], "option_labels": {"brief": "Brief", "detailed": "Detailed"}}, {"row_id": "reminders", "options": ["regular_reminders", "only_important_events"], "option_labels": {"regular_reminders": "Regular reminders", "only_important_events": "Only important events"}}, {"row_id": "steps", "options": ["one_main_step", "few_steps_for_day"], "option_labels": {"one_main_step": "One main step", "few_steps_for_day": "A few steps for the day"}}], "label": "How do you prefer to receive support?"}, {"field_id": "PRG_TONE", "format": "single_choice", "profile_path": "person.communication.tone", "options": ["gentle", "friendly", "close_friend", "direct"], "option_labels": {"gentle": "Gentle - soft and careful, with no jokes", "friendly": "Friendly - natural and easy, with occasional light humor", "close_friend": "Like someone who knows me well - informal, conversational, and okay with jokes", "direct": "Direct - brief, honest, and never overly sweet"}, "label": "How can Momna talk with you?"}]}]}'::jsonb, 'draft')
on conflict (onboarding_key, version, locale) do update
  set schema = excluded.schema, status = 'draft';

do $$
declare v_id uuid;
begin
  for v_id in
    select id from public.onboarding_definitions
    where onboarding_key in ('cycle','pregnancy') and version = 1
  loop
    perform public.publish_onboarding_definition(v_id);
  end loop;
end $$;